local ECSComponent = import("Frame.ECS.ECSComponent")

---@type GroceryHomeDojo
local GroceryHomeDojo = import("Game.Grocery.GroceryHomeDojo")
---@type GroceryConstants
local GroceryConstants = import('Game.Grocery.GroceryConstants')

---@class GroceryComponent
local GroceryComponent = Class("GroceryComponent",ECSComponent)

function GroceryComponent:__init()
    self.name = "GroceryComponent"
    ---@type GroceryHomeDojo
    self._groceryHomeDojo = GroceryHomeDojo.New()
end

function GroceryComponent:__delete()
    self._groceryHomeDojo = nil
end

---初始化
---@param jsonData table 服务器返回的商城数据
function GroceryComponent:Initial(jsonData)
    local homeData = self:ConvertHomeData(jsonData)
    self:GetGroceryHomeDojo():Fill(homeData)
end

---将原始数据转换为需求的数据格式
---@param jsonData table 服务器返回的商城数据
function GroceryComponent:ConvertHomeData(jsonData)
    return jsonData
end

---减少库存
---@param groceryType GroceryConstants.GroceryType
---@param productId   integer 商品id
---@param buyNum      integer 购买数量
function GroceryComponent:ReduceStock(groceryType, productId, buyNum)
    local data = {}
    if groceryType == GroceryConstants.GroceryType.AsyncPVP then
        local originData = self:GetRegionalData()
        data = originData.products
        local productData = {}
        for _, v in ipairs(data) do
            if checkInt(v.productId) == productId then
                productData = v
            end
        end
        -- 增加购买次数
        originData.mallBuyProgress = checkInt(originData.mallBuyProgress) + buyNum * checkInt(productData.prices[1].current)
        -- 改变进度奖励状态
        local rewardsVo = CfUtils.GetCf(AutoIds.IdSetting3089, "StoreAsyncPVPRewardsVo", true)
        for _, v in ipairs(originData.mallBuyRewards) do
            if checkInt(v.status) == 0 then
                if originData.mallBuyProgress >= rewardsVo[checkInt(v.id)].amount then
                    v.status = 1
                end
            end 
        end
    else
        data = checkTable(self:GetGroceryDataByType(groceryType).products)
    end 
    
    for i, v in ipairs(data) do
        if v.stock ~= -1 then
            if checkInt(v.productId) == productId then
                v.currentStock = v.currentStock - buyNum
                break
            end
        end
    end
end

---减少倒计时
---@param deltaTime number 经过的时间
function GroceryComponent:DecreaseTime(deltaTime)
    local coreData = self:GetCoreData()
    if next(coreData) then
        coreData.nextRefreshLeftSeconds = checkNumber(coreData.nextRefreshLeftSeconds) - deltaTime
    end
    
    local catCartData = self:GetCatCartData()
    if next(catCartData) then
        catCartData.nextRefreshLeftSeconds = checkNumber(catCartData.nextRefreshLeftSeconds) - deltaTime
    end
    local function decreaseActivityTime(products)
        for _, v in ipairs(checkTable(products)) do
            if v.activityEndTime and checkNumber(v.activityEndTime) > 0 then
                v.activityEndTime = checkNumber(v.activityEndTime) - deltaTime
            end
        end
    end
    
    decreaseActivityTime(self:GetRegionalData().products)
    decreaseActivityTime(self:GetLadderData().products)
    decreaseActivityTime(self:GetCoreData().products)
    decreaseActivityTime(self:GetCatCartData().products)
    decreaseActivityTime(self:GetWorldBossData().products)
    decreaseActivityTime(self:GetTipData().products)
    decreaseActivityTime(self:GetClubData().products)
    decreaseActivityTime(self:GetLightDarkData().products)
end

---获取GroceryHomeDojo
---@return GroceryHomeDojo
function GroceryComponent:GetGroceryHomeDojo()
    return self._groceryHomeDojo
end

---通过商城类型获取商城数据（需在config中配置dataKey）
---@param groceryType GroceryConstants.GroceryType
function GroceryComponent:GetGroceryDataByType(groceryType)
    local config = GroceryConstants.GroceryNodeConfigs[groceryType]
    if not config or not config.dataKey then return end

    local homeDojo = self:GetGroceryHomeDojo()
    return homeDojo[config.dataKey]
end

